    { role: 'system', content: 'You are a Security Architect producing a risk assessment. Output JSON {"markdown": "..."} only. Markdown must start with "# Risk Assessment:" - no code fences.' },
    { role: 'user', content: 'PROJECT: ' + $json.projectName + '\nBRD: ' + JSON.stringify($json.artifacts.brd || {}).slice(0,6000) + '\nBUSINESS_ARCH: ' + JSON.stringify($json.artifacts.business_arch || {}).slice(0,6000) + '\nAPP_ARCH: ' + JSON.stringify($json.artifacts.application_arch || {}).slice(0,6000) + '\nDATA_ARCH: ' + JSON.stringify($json.artifacts.data_arch || {}).slice(0,4000) + '\nINFRA_ARCH: ' + JSON.stringify($json.artifacts.infrastructure_arch || {}).slice(0,4000) }
  ],
  stream: false,
  format: { type: 'object', required: ['markdown'], properties: { markdown: { type: 'string' } } },
  options: { temperature: $('Initialize Parameters').first().json.ollamaTemperature, seed: $('Initialize Parameters').first().json.ollamaSeed }
} }}

parameters.jsCode:
const raw = $json.message?.content;
let parsed; try { parsed = typeof raw === 'string' ? JSON.parse(raw) : raw; } catch (e) { return [{ json: { valid: false, riskMarkdown: '' } }]; }
const md = String(parsed?.markdown || '');
const fnv1a = (s) => { let h = 0x811c9dc5; for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = (h * 0x01000193) >>> 0; } return ('0000000' + h.toString(16)).slice(-8); };
return [{ json: { valid: md.startsWith('# Risk Assessment:'), riskMarkdown: md, riskHash: fnv1a(md) } }];

