const raw = $json.message?.content;
let p; try { p = typeof raw === 'string' ? JSON.parse(raw) : raw; } catch (e) { return [{ json: { valid: false } }]; }
const fnv1a = (s) => { let h = 0x811c9dc5; for (let i = 0; i < (s||'').length; i++) { h ^= s.charCodeAt(i); h = (h * 0x01000193) >>> 0; } return ('0000000' + h.toString(16)).slice(-8); };
return [{ json: { valid: true, integrationStyle: p.integrationStyle, solutionMarkdown: p.solutionMarkdown || '', openapiYaml: p.openapiYaml, sqlSchemaSql: p.sqlSchemaSql, asyncapiYaml: p.asyncapiYaml, cloudEventsMarkdown: p.cloudEventsMarkdown, avroSchemasJson: p.avroSchemasJson, hashes: { solution: fnv1a(p.solutionMarkdown), openapi: fnv1a(p.openapiYaml), sql: fnv1a(p.sqlSchemaSql) } } }];

const j = $json;
if (!j.valid) return [];
const ctx = $('Pass Context').first().json;
const meta = { jobId: ctx.jobId, stage: 'quality-compliance', integrationStyle: j.integrationStyle };
const out = [];
out.push({ json: { artifactType: 'solution_arch_md', content: { markdown: j.solutionMarkdown }, contentHash: j.hashes.solution, meta } });
if (j.openapiYaml) out.push({ json: { artifactType: 'openapi_yaml', content: { yaml: j.openapiYaml }, contentHash: j.hashes.openapi, meta } });
if (j.sqlSchemaSql) out.push({ json: { artifactType: 'sql_schema_sql', content: { sql: j.sqlSchemaSql }, contentHash: j.hashes.sql, meta } });
return out;

