const ctx = $('Pass Context').first().json;
const risk = $('Validate Risk').first().json;
const sol = $('Validate Solution').first().json;
const qa = $('Validate QA').first().json;
const projectSlug = ctx.projectSlug;
const jobId = ctx.jobId;
const repoDir = '/opt/workspace/software-delivery';
const projectDir = repoDir + '/' + projectSlug + '-docs';
const remote = 'git@github.com:shlapolosa/software-delivery.git';

let sh = 'set -e
mkdir -p /opt/workspace
';
sh += "if [ ! -d '" + repoDir + "/.git' ]; then git clone '" + remote + "' '" + repoDir + "'; fi
";
sh += "cd '" + repoDir + "'
git fetch origin
";
sh += "git checkout -B '" + projectSlug + "' 'origin/" + projectSlug + "' 2>/dev/null || git checkout -B '" + projectSlug + "'
";
sh += "mkdir -p '" + projectDir + "/docs' '" + projectDir + "/api' '" + projectDir + "/db'
";

sh += "cat > '" + projectDir + "/docs/risk-assessment.md' <<'EOF_" + jobId + "'
" + risk.riskMarkdown + "
EOF_" + jobId + "
";
sh += "cat > '" + projectDir + "/docs/solution-architecture.md' <<'EOF_" + jobId + "'
" + sol.solutionMarkdown + "
EOF_" + jobId + "
";
sh += "cat > '" + projectDir + "/docs/test-strategy.md' <<'EOF_" + jobId + "'
" + qa.testStrategyMarkdown + "
EOF_" + jobId + "
";
sh += "cat > '" + projectDir + "/docs/test-scenarios.md' <<'EOF_" + jobId + "'
" + qa.testScenariosMarkdown + "
EOF_" + jobId + "
";
if (sol.openapiYaml) sh += "cat > '" + projectDir + "/api/openapi.yaml' <<'EOF_" + jobId + "'
" + sol.openapiYaml + "
EOF_" + jobId + "
";
if (sol.sqlSchemaSql) sh += "cat > '" + projectDir + "/db/schema.sql' <<'EOF_" + jobId + "'
" + sol.sqlSchemaSql + "
EOF_" + jobId + "
";

sh += "git add '" + projectSlug + "-docs'
";
sh += "git commit -m 'Add QC artifacts for " + projectSlug + " (job " + jobId + ")' || true
";
sh += "git push -u origin '" + projectSlug + "'
";

return [{ json: { ...ctx, gitScript: sh } }];
